    adcs_vec3_t perp;
    adcs_vec3_t m;
    double b2;
    double parallel;
    double n;
    double scale;

    if ((field_body_t == NULL) || (field_rate_t_s == NULL) || (command == NULL)) {
        if (command != NULL) {
            command->command = (adcs_vec3_t){0, 0, 0};
            command->saturated_axes = 0U;
        }
        return ADCS_E_NULL;
    }

    command->command = (adcs_vec3_t){0, 0, 0};
    command->saturated_axes = 0U;

    if ((!adcs_is_finite_vec3(field_body_t)) || (!adcs_is_finite_vec3(field_rate_t_s)) ||
        (!isfinite(normalized_gain_nm_s_t)) || (!isfinite(max_dipole_a_m2)) ||
        (normalized_gain_nm_s_t < 0.0) || (max_dipole_a_m2 < 0.0)) {
        return ADCS_E_RANGE;
    }

    b2 = adcs_vec3_dot(field_body_t, field_body_t);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        return ADCS_E_DEGENERATE;
    }

    parallel = adcs_vec3_dot(field_rate_t_s, field_body_t) / b2;
    parallel_part = adcs_vec3_scale(field_body_t, parallel);
    perp = adcs_vec3_sub(field_rate_t_s, &parallel_part);

    m = adcs_vec3_scale(&perp, -normalized_gain_nm_s_t / b2);

    n = adcs_vec3_norm(&m);
    if (n > max_dipole_a_m2) {
        scale = max_dipole_a_m2 / n;
        m = adcs_vec3_scale(&m, scale);
        command->saturated_axes = 7U;
    }

    command->command = m;
    return ADCS_OK;
}

